-- SCRIPT BACKUP DỮ LIỆU LỊCH SỬ TỪ GOOGLE APPSHEET — BẾN BÃI SƠN CẢNG
-- Nguồn: docs/Xe-ra-vao_SC.xlsx (Trích xuất ngày 16/10/2026)
-- Số lượng: 360 lượt xe, 304 lượt container
-- Phục vụ: Lưu trữ dự phòng (Backup) & Tra cứu đối soát lịch sử (Legacy Audit)
-- =============================================================================

-- 1. BẢNG LƯU TRỮ XE LỊCH SỬ APPSHEET
CREATE TABLE IF NOT EXISTS legacy_appsheet_vehicles (
    id SERIAL PRIMARY KEY,
    legacy_id VARCHAR(50) UNIQUE NOT NULL,
    license_plate VARCHAR(30) NOT NULL,
    vehicle_type VARCHAR(50),
    entry_time TIMESTAMPTZ,
    entry_by VARCHAR(100),
    exit_time TIMESTAMPTZ,
    exit_by VARCHAR(100),
    inbound_container_no VARCHAR(30),
    inbound_container_id VARCHAR(50),
    outbound_container_no VARCHAR(30),
    outbound_container_id VARCHAR(50),
    ticket_amount_payable NUMERIC(15,2) DEFAULT 0,
    ticket_status VARCHAR(50),
    ticket_payment_method VARCHAR(50),
    vehicle_status VARCHAR(30),
    storage_fee_confirmed VARCHAR(50),
    storage_fee_note TEXT,
    note TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. BẢNG LƯU TRỮ CONTAINER LỊCH SỬ APPSHEET
CREATE TABLE IF NOT EXISTS legacy_appsheet_containers (
    id SERIAL PRIMARY KEY,
    legacy_id VARCHAR(50) UNIQUE NOT NULL,
    container_no VARCHAR(30) NOT NULL,
    inbound_vehicle_id VARCHAR(50),
    entry_time TIMESTAMPTZ,
    entry_by VARCHAR(100),
    outbound_vehicle_id VARCHAR(50),
    exit_time TIMESTAMPTZ,
    exit_by VARCHAR(100),
    night_count INT DEFAULT 0,
    tariff_rate_night NUMERIC(15,2) DEFAULT 100000,
    storage_amount_payable NUMERIC(15,2) DEFAULT 0,
    storage_status VARCHAR(50),
    storage_payment_method VARCHAR(50),
    container_status VARCHAR(30),
    cargo_status VARCHAR(50),
    note TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

